def solve2(I, bboxall=False):
    from collections import Counter
    H,W=len(I),len(I[0]); c=Counter(v for row in I for v in row)
    bg=c.most_common(1)[0][0]
    fgc=[v for v in c if v!=0 and v!=bg][0]
    cells=[(i,j) for i in range(H) for j in range(W) if I[i][j]==fgc]
    mr=min(i for i,j in cells); mc=min(j for i,j in cells)
    S={(i-mr,j-mc) for i,j in cells}
    h=max(i for i,j in S); w=max(j for i,j in S)
    out=[row[:] for row in I]; offs=[]
    for di in range(H-h):
        for dj in range(W-w):
            if bboxall:
                ok=all(I[di+a][dj+b]==0 for a in range(h+1) for b in range(w+1))
            else:
                ok=all(I[di+a][dj+b]==0 for a,b in S)
            if ok:
                offs.append((di-mr,dj-mc))
                for a,b in S: out[di+a][dj+b]=fgc
    return out,offs
