def solveB(I, target=0, shcol=None):
    from collections import Counter
    H,W=len(I),len(I[0]); c=Counter(v for row in I for v in row)
    if shcol is None:
        shcol=min((v for v in c if v!=target), key=lambda v:c[v])
    cells=[(i,j) for i in range(H) for j in range(W) if I[i][j]==shcol]
    mr=min(i for i,j in cells); mc=min(j for i,j in cells)
    S={(i-mr,j-mc) for i,j in cells}
    h=max(i for i,j in S); w=max(j for i,j in S)
    out=[row[:] for row in I]; offs=[]
    for di in range(H-h):
        for dj in range(W-w):
            if all(I[di+a][dj+b]==target for a,b in S):
                offs.append((di-mr,dj-mc))
                for a,b in S: out[di+a][dj+b]=shcol
    return out,offs,shcol
